const rows = $input.all();
if (rows.length === 0) {
  return [{ json: { http_status: 404, body: { ok: false, error: 'Unknown job_id.' } } }];
}
const j = rows[0].json;
const body = {
  ok: true,
  job_id: j.job_id,
  case_id: j.case_id,
  status: j.status,
  attempt: j.attempt,
  created_at: j.created_at,
  completed_at: j.completed_at
};
if (j.status === 'complete') {
  body.report_md_path = j.report_md_path;
  body.report_json_path = j.report_json_path;
  body.risk_rating = j.risk_rating;
  body.recommended_decision = j.recommended_decision;
  body.executive_summary = j.executive_summary;
}
if (j.status === 'failed') {
  body.error = j.error;
}
return [{ json: { http_status: 200, body } }];
